update public.barangays b set boundary = extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_buffer(extensions.st_buffer(
  extensions.st_difference(
    extensions.st_union(b.boundary, coalesce(extensions.st_setsrid(extensions.st_geomfromgeojson(p.add_g), 4326), extensions.st_geomfromtext('POLYGON EMPTY', 4326))),
    coalesce(extensions.st_setsrid(extensions.st_geomfromgeojson(p.sub_g), 4326), extensions.st_geomfromtext('POLYGON EMPTY', 4326))),
  0.000003), -0.000003)), 3))
from patch p where b.psgc_code = p.code;
